custom_css:
/* ======================================================
   美化页面设计：腋毛殿下
   美化代码实现：凝嘤嘤
   感谢每一位代码老师的伟大贡献！感谢您的使用~
======================================================  */
@import url("https://fontsapi.zeoseven.com/285/main/result.css");

body {
    font-family: "Noto Serif CJK";
    font-weight: normal;
}
/* ===== 1. 彻底摧毁酒馆原生布局与幽灵组件 ===== */
.mes .mes_block,
.mes .mes_main,
.mes .mesAvatarWrapper,
.mes .name_and_status,
.mes .mes_header {
    display: block !important;
    background: transparent !important;
    padding: 0 !important;
    margin: 0 !important;
    position: static !important;

    /* 🌟【粉碎滚动框核心 1】：强行解除父级容器的所有高度束缚 */
    min-height: 0 !important;
    height: auto !important;
    max-height: none !important;
    overflow: visible !important; /* 绝对禁止出现滚动条 */

    /* 👉此处强制占据 100% 宽度的思路，源自 @inkfoxxxx 老师分享的“文字布满消息框，肘击右侧留空”代码。 */
    width: 100% !important; 
    box-sizing: border-box !important; 
}

/* 💀 强行封杀酒馆右侧隐藏的按钮和滑动感应区，防止它们挤压文字 */
.mes .mes_buttons { position: absolute !important; right: 10px !important; top: 10px !important; margin: 0 !important; }
.mes .swipe-left, .mes .swipe-right { display: none !important; }

/* ===== 2. 对话框：定义唯一物理坐标系 & 绝对对称居中 ===== */
.mes {
    display: block !important;
    position: relative !important; 
    background-color: #FFFFFF !important;
    border-radius: 0px !important;
    border: none !important;

    /* 🌟【绝对对称算法】：强制把内外边距全算进宽度里 */
    box-sizing: border-box !important; 

    /* 📍【蓝色区域留白】：利用外阴影向上撑出纯白空间 */
    box-shadow: 0 -90px 0 0 #FFFFFF, inset 0 0 0 4px #FFFFFF, inset 0 0 0 5px #000000 !important;

    /* 📍【桌面端对称留白】：左40px，右40px，丝毫不差。顶部留出130px给头像和名字 */
    padding: 130px 40px 30px 40px !important;

    /* 🌟【外部绝对居中】：占据屏幕 90% 并用 auto 居中，确保外部左右留白绝对一致！ */
    width: 90% !important; 
    max-width: 900px !important;
    margin: 90px auto 30px auto !important; 

    /* 🌟【粉碎滚动框核心 2】：气泡本体高度无限向下延伸，绝不截断 */
    height: auto !important; 
    max-height: none !important; 
    overflow: visible !important; /* 解除上一版的隐藏封印，彻底告别滚动条！ */
}

/* ===== 3. 头像：锁死正方形，钉在左上角 ===== */
.mes .mes_avatar, 
.mes .avatar, 
.mesAvatarWrapper .avatar {
    position: absolute !important;
    top: 20px !important;  
    left: 20px !important; 

    width: 140px !important;   
    height: 140px !important;  
    min-width: 140px !important;
    min-height: 140px !important;
    max-width: 140px !important;
    max-height: 140px !important;

    padding: 0 !important;
    margin: 0 !important;
    z-index: 10 !important;
}

.mes .avatar img, 
.mes_avatar img, 
.mes img[src*="/thumbnail"] {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    border-radius: 0px !important;
    display: block !important;
}
/* ===== 3.1 头像专属贴纸（覆盖在头像上） ===== */
/* 利用伪元素在头像容器上生成一个覆盖层 */
.mes .mes_avatar::after, 
.mes .avatar::after, 
.mesAvatarWrapper .avatar::after {
    content: "" !important;
    position: absolute !important;
    display: block !important;

    /* 📍【贴纸图片替换】 */
    background-image: url('https://iili.io/q01Imo7.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;

    /* 📍【贴纸尺寸微调】 */
    width: 60px !important;   /* ✏️ 贴纸的宽度：嫌小改大（如 80px） */
    height: 60px !important;  /* ✏️ 贴纸的高度：嫌小改大（如 80px） */

    /* 📍【贴纸坐标微调】（坐标是相对于头像框的） */
    top: -35px !important;    /* ✏️ 上下移动：负数代表往上飞出头像框，正数代表往下沉 */
    left: -15px !important;   /* ✏️ 左右移动：负数代表往左飞出头像框，正数代表往右移 */
    /* 💡 如果你想把它放在头像右下角，可以删掉 top/left，改成：
       bottom: -10px !important; 
       right: -10px !important; 
    */

    /* 🌟【覆盖层级】 */
    z-index: 20 !important; /* 强制设为 20，确保它盖在头像 (z-index:10) 的正上方 */

    /* 👉防止伪元素遮挡底部按钮或头像的点击事件，引用自 @lambkinling 老师的教学。 */
    pointer-events: none !important; 
}
/* ===== 4. 角色名字 (第一排) ===== */
.mes .ch_name {
    position: absolute !important;
    top: 55px !important;   
    left: 175px !important; 

    /* 🌟【自适应换行核心】 */
    right: 40px !important; /* 告诉名字：右边距40px就是墙，碰到必须换行 */
    max-width: calc(100% - 215px) !important; /* 限制最大宽度 */
    /* 👉 允许长角色名折行显示的思路与代码，引用自 @秋依 和 @ca 老师分享的“长 char 名完全显示”方案。 */
    white-space: normal !important; /*  允许换行  */
    overflow-wrap: break-word !important; /* 如果遇到超长英文，强制折断换行 */

    font-size: 18px !important;
    line-height: 1.2 !important;
    margin: 0 !important;
    text-align: left !important;
}

/* ===== 5. 专属文案 (第二排，自适应跟随) ===== */
.mes .ch_name::after {
    content: "“你是巨大的海洋，我是雨下在你身上”"; 

    /* 👉 利用 ::after 在已有元素后方添加专属自定义文案的底层逻辑，出自 @Soleil 和 @Nakari (NA) 老师分享的自定义教学。 */
    /*  🌟【防重叠黑科技】：放弃绝对的 top 坐标，改为 relative（相对跟随）！
       这样即使上一排的名字换行变成了两排，这段文案也会自动被“挤”下去，绝不重叠，且不改变它原本左右对齐的位置！ */
    position: relative !important;
    top: auto !important; 
    left: auto !important;
    margin-top: 6px !important; /* 距离名字最后一行的间距 */

    display: block;
    width: 100% !important;
    max-width: 300px !important; /* 桌面端依然保持最大宽度 */
    font-size: 13px !important;
    white-space: normal !important;
}

/* ===== 6. 第三排：ID、Token、时间戳 与 Timer ===== */
/* 清除原生父容器可能带来的干扰 */
.mes .mes_status,
.mes .name_and_status {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
}

/* 🎯【核心打击】：直接点名这四个元素，强制脱离原文档流 */
.mes .timestamp,
.mes .mesIDDisplay,
.mes .tokenCounterDisplay,
.mes .mes_timer {
    /* 👉 使用绝对定位 (absolute) 将元素固定在界面的指定位置，思路引用自 @tenplustwo_equalto_12(十二) 老师和 @Nakari 老师的布局方案。 */
    position: absolute !important;
    top: 125px !important; 

    font-size: 12px !important;       
    line-height: 1.2 !important; /* 稍微增加行高，换行后文字看起来不会粘在一起 */
    font-weight: normal !important;

    /* 🌟移除了之前统一定义的 nowrap，为时间戳的自适应让路 */

    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    margin: 0 !important;
    padding: 0 !important;
    display: block !important;
    z-index: 10 !important;
}

/* 📍 1. 消息ID (#2) */
.mes .mesIDDisplay {
    left: 175px !important; 
    white-space: nowrap !important; /* ID 很短，保留绝不换行 */
}

/* 📍 2. Token计数 (10745t) */
.mes .tokenCounterDisplay {
    left: 215px !important; 
    white-space: nowrap !important; /* Token 数据保留绝不换行 */
}

/* 📍 3. 时间戳 (Timestamp) */
.mes .timestamp {
    left: 0px !important; 
    top: 90px !important; 

}

/* 📍 4. 计时器 (Timer) */
.mes .mes_timer {
    left: 270px !important; 
    white-space: nowrap !important; /* Timer 保留不换行 */
}

/* ===== 7. 聊天正文：控制所有方向的间距 ===== */
.mes .mes_text {
    display: block !important;
    width: 100% !important;
    margin: 0 !important;

    /* 📍【核心控制区：正文上下左右留白】 
       这里的四个数字顺序依次是：上、右、下、左 (顺时针)
       - 第1个 (45px)：距离上方头像/名字的距离。
       - 第2个 (20px)：【右侧留白】。改大(如 40px)，文字右边会更往里缩。
       - 第3个 (0)   ：下方距离。
       - 第4个 (20px)：【左侧留白】。改大(如 40px)，文字左边会更往里缩。
       ⚠️ 注意：要保证左右对称，请让第2个和第4个数字保持一样大！ */
    padding: 45px 0px 0 0px !important; 

    box-sizing: border-box !important;
    border-top: none !important; 

    text-align: left !important;
    line-height: 1.6 !important;
}

.mes .mes_text p, 
.mes .mes_text div {
    text-align: left !important;
}

/* ===== 8. 思维链 (CoT) 贴图替换与滚动框 ===== */
.mes_reasoning_header_title,
.mes_reasoning_arrow,
.mes_reasoning_header span,
.mes_reasoning_header i {
    /* 👉 隐藏思维链箭头 (.mes_reasoning_arrow) 的代码引用自 @hy 老师；隐藏思维链标题的方法引用自 @Nakari 老师的分享。 */
    display: none !important;
}

.mes_reasoning_header {
    display: block !important;
    width: 100% !important;
    height: 36px !important; 

    background-image: url('https://iili.io/qjShZTQ.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: left !important;

    background-color: transparent !important;
    border: none !important;
    margin-bottom: 10px !important;
    cursor: pointer !important;

    position: absolute !important;
    top: 12px !important; 
    left: 165px !important; 
}

/* 📍【思维链展开后的滚动内容框】 */
.mes_reasoning {
    background-color: rgba(0, 0, 0, 0.03) !important;
    border: 1px dashed #cccccc !important;
    padding: 15px !important;
    font-size: 13px !important;
    color: #666666 !important;
    text-align: left !important;
    border-radius: 0px !important;
    margin-top: 30px;
    /* 🌟【滚动框核心指令】 */
    max-height: 250px !important; /* ✏️ 控制框的最大高度。如果嫌框太大/太小，修改这个数值即可 (例如 200px 或 300px) */
    overflow-y: auto !important;  /* 🌟 内容超过上面设定的高度时，自动出现纵向滚动条 */
    display: block !important;
}

/* 🌟【思维链滚动条美化】（让滚动条变细、变优雅，不破坏整体排版） */
.mes_reasoning::-webkit-scrollbar {
    /* 👉滚动条变细、透明滑轨和重绘滑块等核心代码，引用自 @inkfoxxxx、@lambkinling 和 @blue_0310. 等老师。 */
    width: 6px !important; /*  滚动条宽度  */
}
.mes_reasoning::-webkit-scrollbar-thumb {
    background: #cccccc !important; /* 滚动条颜色 */
    border-radius: 3px !important;  /* 滚动条圆角 */
}
.mes_reasoning::-webkit-scrollbar-track {
    background: transparent !important; /* 滚动条轨道透明 */
}

/* ===== 9. 顶部导航栏 (#top-settings-holder) 图标缩小与半透明 ===== */
/* 🎯 暴力选中 #top-settings-holder 内所有的菜单按钮、图标、SVG 和图片 */
#top-settings-holder .menu_button,
#top-settings-holder .drawer-toggle,
#top-settings-holder i,
#top-settings-holder .fas,
#top-settings-holder .fa-solid,
#top-settings-holder svg,
#top-settings-holder img {
    /* 📍【透明度微调】 
       0.5 代表 50% 透明度。越接近 0 越透明，越接近 1 越实心 */
    opacity: 0.5 !important; 

    /* 📍【大小微调】 
       0.8 代表缩小到原本的 80%。嫌大就改成 0.7，嫌小就改成 0.9 */
    transform: scale(0.8) !important; 

    /* 👉图标的放大和透明度过渡动画，引用自 @lambkinling(咩野) 和 @inkfoxxxx 老师分享的过渡效果代码。 */
    transition: all 0.3s ease !important; 
}

/* 🌟【交互升级】：当你的鼠标悬停在图标上时，让它亮起并稍微变大，方便你点击 */
#top-settings-holder .menu_button:hover,
#top-settings-holder .drawer-toggle:hover,
#top-settings-holder i:hover,
#top-settings-holder .fas:hover,
#top-settings-holder .fa-solid:hover,
#top-settings-holder svg:hover,
#top-settings-holder img:hover {
    opacity: 1 !important; /* 鼠标放上去时恢复 100% 亮度 */
    transform: scale(0.95) !important; /* 鼠标放上去时放大一点点 */
}

/* ======================================================
   修复底部发送区域 (#send_form) 行数变多时出现裂缝的问题
   原理：消除小数点像素渲染误差，固定背景原点
====================================================== */

#send_form {
    /* 1. 依然贴上你的格纹图片，并设置为全方位平铺 */
    background-image: url('https://iili.io/qV48DSs.png') !important;
    background-repeat: repeat !important;
    background-size: 500px !important; 

}

/* ======================================================
   终极修复：旧图标彻底粉碎 & 提示词自适应绝对居中
   原理：抛弃像素坐标，使用 Flexbox 引擎自动寻找中心点
====================================================== */

/* 🎯 1. 【斩草除根】连同伪元素一起彻底抹除旧图标 */
#options_button::before, #options_button *,
#extensionsMenuButton::before, #extensionsMenuButton *,
#send_but::before, #send_but *,
#send_button::before, #send_button * {
    /* 👉将底栏原始图标的 ::before 伪元素彻底隐藏，从而实现干净的背景图替换，引用自 @inkfoxxxx 老师。 */
    content: none !important;     /*  杀掉原生 FontAwesome 伪元素图标！  */
    display: none !important; 
}

#options_button,
#extensionsMenuButton,
#send_but,
#send_button {
    font-size: 0 !important; 
    color: transparent !important; 
    /* 👉 将原生按钮强行无框化和透明处理，化用自 @captivating_fox_43571 (hy) 老师和 @lambkinling (咩野) 老师的代码。 */
    border: none !important; 
    background-color: transparent !important;
}

/* 🎯 2. 贴上你的专属新图标 */
#options_button { background: url('https://iili.io/qV6Gpix.png') center/24px 24px no-repeat !important; }
#extensionsMenuButton { background: url('https://iili.io/qV6NtMF.png') center/26px 26px no-repeat !important; }
#send_but, #send_button { background: url('https://iili.io/qV6gTdX.png') center/24px 24px no-repeat !important; }

/* 增加鼠标悬停时的微小放大互动 */
#options_button:hover,
#extensionsMenuButton:hover,
#send_but:hover,
#send_button:hover {
    transform: scale(1.15) !important;
    transition: transform 0.2s ease !important;
}


/* 🎯 3. 【无坐标·绝对正中间】自定义发送框文字 */

/* 步骤 A：把原生无聊的提示词彻底变透明 */
#send_textarea::placeholder {
    /* 👉 将原生占位符字体变透明，为后续挂载假提示词让路，引用自 @inkfoxxxx 及 @hgu0755 老师。 */
    color: transparent !important;
}

/* 步骤 B：给输入框的直接父级加上相对定位 */
#nonQRFormItems {
    position: relative !important;
}

/* 步骤 C：使用自适应魔法，自动锁定中心！ */
#nonQRFormItems::after {
    content: "@署名：將我的悲傷葬在雨季" !important;
    position: absolute !important;

    /* 🚀 【告别像素坐标】：直接拉满四个方向，让它铺满整个输入行 */
    top: 0 !important;
    bottom: 0 !important;
    left: 0 !important;
    right: 0 !important;

    /* 🚀 【自动雷达居中】：开启弹性盒子，无论设备怎么变，永远死死锁定在正中间！ */
    display: flex !important;
    align-items: center !important;      /* 绝对垂直居中 */
    justify-content: center !important;  /* 绝对水平居中 */

    color: #888888 !important;   /* 文字颜色 */
    font-size: 14px !important;  /* 字体大小 */

    pointer-events: none !important; /* 保证鼠标点击能穿透文字，选中底下的输入框 */
    opacity: 0 !important;
    transition: opacity 0.2s ease !important;
    z-index: 20 !important;
}

/* 步骤 D：打字时自动隐藏专属签名 */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::after {
    /* 👉 使用 :has 配合 placeholder-shown 控制提示词仅在没有输入时显示，源于 @inkfoxxxx 老师的原创分享。 */
    opacity: 1 !important; 
}

/* ======================================================
   终极美化：正文段落 (p) 虚线下划线效果
   原理：使用现代 text-decoration 属性，不破坏行高与盒子模型
====================================================== */

q {
    background: transparent !important;
    border: none !important;
    border-right: 0px solid transparent !important;
    border-left: 0px solid transparent !important;
    border-radius: 0 !important;

    /* 左右留出 3px 空间，下方留出 1px 给虚线呼吸感 */
    padding: 0px 3px 1px 3px !important;

    /* 👉 利用 CSS 为 q 标签（常用于引用块）添加花式虚线边框，出自 @inkfoxxxx 老师的长篇教程。 */
    border-bottom: 1px dashed currentColor !important; 

    /* 保证行高不被破坏 */
    line-height: inherit !important;
}

/* ======================================================
   终极全屏无缝隙适配（参考无滚动条与贴边布局）
   核心：消灭所有外部留白，隐藏系统滚动条，打造极致沉浸感
====================================================== */

================================================ */
/* 👉 彻底隐藏系统 Webkit 滚动条，打破屏幕边缘的物理隔阂，引用自 @lambkinling(咩野) 老师的教学。 */
::-webkit-scrollbar {
    display: none !important;
}

/* 🎯 2. 彻底重置聊天主容器，剥夺酒馆自带的左右留白 */
#chat {
    padding-left: 0 !important;
    padding-right: 0 !important;
    margin: 0 !important;
    width: 100% !important;
    max-width: 100% !important;
    overflow-x: hidden !important; /* 绝对禁止出现横向空白/滚动 */
    align-items: center !important;
}

/* 🎯 3. 气泡100%贴合屏幕，真正实现无缝接壤 */
/* 👉 将 width 设为 100% 并抹除左右 margin 和边框的极致贴边设计，出自 @inkfoxxxx 老师分享的“超级大宽屏”思路。 */
#chat .mes {
    /* 撕掉之前的 90% 宽度和 900px 封印 */
    width: 100% !important; 
    max-width: 100% !important;

    /* 强制清零左右外边距，让底色紧紧贴住屏幕两侧 */
    margin-left: 0 !important;
    margin-right: 0 !important;

    /* 移除边缘圆角，让方块完美契合屏幕直角 */
    border-radius: 0px !important;

    /* 左右边框也一并抹除，防止在边缘留下一丝黑线 */
    border-left: none !important;
    border-right: none !important;

    /* 内部文字留白：为了防止文字真的贴死在屏幕边缘，我们保留内部安全距离 */
    /* 使用响应式单位 vw（视口宽度），让它在手机和电脑上都看起来很舒服 */
    padding-left: 4vw !important; 
    padding-right: 4vw !important;
    box-sizing: border-box !important;
}

/* 🎯 4. 如果你有背景图/夜间底色，确保它是完全铺满的 */
body, #bg_all, #main_wrapper {
    background-color: #FFFFFF !important; /* 确保最底层也是夜间模式底色，防止滑动时漏出白边 */
}

/* ======================================================
   精准修复：保留完美的上下间距，并一劳永逸地“填充颜色”
   听从你的指导：绝不删 margin，只把空隙涂满夜间底色！
====================================================== */

/* 🎯 1. 填色魔法：直接给聊天的“总底板”刷上相同的夜间深灰。
   这样不管你的气泡上下 margin 隔了多远，透明缝隙透出来的全都是完美的同色背景！
   直接挡住了后面原本绿绿黄黄的背景。 */
#chat {
    background-color: #FFFFFF !important; 
}

/* 🎯 2. 气泡本体：恢复你最完美的排版距离！ */
.mes {
    /* 把你截图里的 90px 上边距 和 30px 下边距 完完整整地还给你！绝不让它们挤在一起！ */
    margin: 90px 0 30px 0 !important; 

    background-color: #FFFFFF !important;

    /* 恢复你原本精致的内发光边框，同时清理掉之前我瞎写的补丁外阴影 */
    box-shadow: inset 0 0 0 4px #FFFFFF, inset 0 0 0 5px #555555 !important;
}

/* ======================================================
   正文文字：恢复绝对对称的 20px 呼吸感留白 + 两端对齐
====================================================== */

.mes .mes_text {
    /* 🎯 1. 听你的：左右各留出精准的 20px 间距，一丝不苟的对称！ */
    padding-left: 20px !important;
    padding-right: 20px !important;

    /* 强行清零外边距，防止被酒馆原生的隐形布局给挤歪 */
    margin-left: 0 !important;
    margin-right: 0 !important;

    /* 🎯 2. 继续保留“两端对齐(justify)”*/
    /* 👉让右侧文字像书本一样方正平齐，引用自 @lambkinling(咩野) 老师分享的“正文文字对齐方式”。 */
    text-align: justify !important;

    /* 👉 确保文字占满设定区域的 100%，引用自 @inkfoxxxx 老师分享的“文字布满消息框，肘击右侧留空”代码。 */
    width: 100% !important;
    box-sizing: border-box !important;
}

/* 🎯 3. 约束段落标签 (p)，防止它自己乱跑破坏我们定好的 20px 界线 */
.mes .mes_text p {
    padding-left: 0 !important;
    padding-right: 0 !important;
    margin-left: 0 !important;
    margin-right: 0 !important;
    text-align: justify !important;
}

/* 1. 小铅笔等操作按钮位置控制 */
.mes .mes_buttons {
    position: absolute !important;
    top: 0px !important;    /* ✏️ 在这里微调小铅笔的高低 */
    right: 0px !important; 
    z-index: 20 !important;
}

/* 2. 编辑输入框样式 */
.mes .mes_edit {
    width: 100% !important;
    box-sizing: border-box !important;
    background: #0006 !important; 
    color: #e0e0e0 !important;
    border: 1px solid #fff4 !important;
    border-radius: 4px !important;
    padding: 8px !important;
    margin-bottom: 5px !important;
    resize: vertical !important;
}

/* 3. 按钮容器：防溢出、居中、自动折行 */
.mes .mes_edit_buttons {
    width: 100% !important;
    box-sizing: border-box !important;
    justify-content: center !important;
    flex-wrap: wrap !important;
    gap: 8px !important;
    margin-top: 5px !important;
    padding: 0 !important;
}

/* 4. 文字按钮(保存/取消)：去模糊、高清化、缩小UI */
.mes .mes_edit_buttons button:not(:has(i,svg)) {
    font-size: 12px !important;
    font-weight: 600 !important;
    transform: none !important; /* 核心：禁止缩放，解决文字发虚 */
    padding: 5px 12px !important;
    border-radius: 4px !important;
    background: #fff2 !important;
    color: #fff !important;
    border: 1px solid #fff4 !important;
    margin: 0 !important;
    white-space: nowrap !important;
    transition: .2s !important;
}

/* 按钮悬停效果 */
.mes .mes_edit_buttons button:not(:has(i,svg)):hover {
    background: #fff4 !important;
    border-color: #fff6 !important;
}

/* 5. 绝对保护小铅笔等图标不长框 */
.mes .mes_button, 
.mes .mes_edit_buttons button:has(i,svg) {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    transform: none !important;
}

/* ======================================================
   终极填坑：修复右滑时全部内容坍塌、头像与正文乱飞 Bug
   修正原理：彻底封杀导致坐标系崩溃的 transform 变换，
   并精准狙杀酒馆 JS 临时生成的绝对定位克隆体。
====================================================== */

/* 1. 强行镇压酒馆的滑动动画，守护你精心设计的坐标原点！ */
.mes .mes_block,
.mes .mes_main,
.mes .mes_text,
.mes .swipe-container,
.mes .mes_swipe_container {
    transform: none !important;
    transition: none !important; /* 砍掉引起错位的滑动特效，改为瞬间切换，保命要紧 */
}

/* 2. 隐形狙击：精准抹杀 JS 临时生成的“滑动残影克隆体”
   它带有内联的 absolute 属性，一出现就会扰乱高度并导致重叠，直接隐藏！ */
.mes .mes_main > .mes_text[style*="absolute"],
.mes .mes_main > .mes_text[style*="position: absolute"],
.mes .mes_main > .mes_text[style*="position:absolute"] {
    display: none !important;
    opacity: 0 !important;
    pointer-events: none !important;
}
/* ======================================================
   补充狙击：彻底锁死右滑时的头像 (img) 与名字模块
   原理：没收酒馆对 .name_and_status 和头像容器施加的平移和过渡动画，
   让头像真正“焊死”在左上角的绝对坐标上，杜绝任何位移！
====================================================== */
.mes .mes_avatar,
.mes .avatar,
.mesAvatarWrapper,
.mesAvatarWrapper .avatar,
.mes .name_and_status,
.mes .mes_avatar img,
.mes .avatar img {
    transform: none !important;
    transition: none !important;
    animation: none !important;
}
